			FD_ZERO(&set);
			FD_SET(sock, &set);
			tv.tv_sec = 0;
			tv.tv_usec = 0;
			select(sock + 1, &set, NULL, NULL, &tv);
			if (FD_ISSET(sock, &set)) {
				/* Okay, there's something ready for
				 * reading here */
				int rv;
				if ((rv =
				     read_packet_check_header(sock,
							      (testflags &
							       TEST_WRITE) ? 0 :
							      1024, i)) < 0) {
					if (!(testflags & TEST_EXPECT_ERROR)
					    || rv != -2) {
						retval = -1;
					} else {
						printf("\n");
					}
					goto err_open;
				} else {
					if (testflags & TEST_EXPECT_ERROR) {
						retval = -1;
						goto err_open;
					}
				}
				--requests;
			}
		} while (FD_ISSET(sock, &set));
