void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos)
{
	off_t block;
	int depth, i;
	int len;

	if (ppos)
		*ppos = pos % TREEPAGESIZE;
	block = pos / TREEPAGESIZE;
	depth = tree_depth(size);
	len = strlen(name);
	for (i = depth - 1; i >= 0; i--) {
		// digit i of block in base TREEDIRSIZE, from MSB
		int digit = (block / pow1024(i)) % TREEDIRSIZE;
		len += snprintf(name + len, lenmax - len, "/TREE%04d", digit);
	}
	snprintf(name + len, lenmax - len, "/FILE%04d", block % TREEDIRSIZE);
}
```

