/**
 * Read from a treefiles export. Reads are limited to the block file
 * containing the offset, so a single read may be satisfied by several
 * calls. Missing block files read as zeroes.
 */
static ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client)
{
	char path[PATH_MAX];
	off_t foffset;
	ssize_t retval;
	int fd;

	if (len > TREEPAGESIZE - (a % TREEPAGESIZE))
		len = TREEPAGESIZE - (a % TREEPAGESIZE);

	strncpy(path, client->exportname, sizeof(path) - 1);
	path[sizeof(path) - 1] = '\0';
	construct_path(path, sizeof(path), client->exportsize, a, &foffset);

	fd = open(path, O_RDONLY);
	if (fd < 0) {
		if (errno == ENOENT) {
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	retval = pread(fd, buf, len, foffset);
	close(fd);
	if (retval >= 0 && (size_t)retval < len) {
		/* the block file is shorter than the data requested;
		 * never-written data reads back as zeroes */
		memset(buf + retval, 0, len - retval);
		retval = len;
	}
	return retval;
}
```

