```c
/**
 * Calculate the number of levels of TREE directories needed to hold an
 * export of the given size. At each level, a directory holds up to
 * TREEDIRSIZE files or subdirectories; the deepest level holds the
 * block files. A depth of 0 means the block files live directly in the
 * export's root directory.
 *
 * @param size the size of the export in bytes
 * @return the number of TREE directory levels required
 **/
static int tree_depth(off_t size) {
	off_t nblocks;
	off_t capacity = TREEDIRSIZE;
	int depth = 0;

	nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	while (capacity < nblocks) {
		depth++;
		capacity *= TREEDIRSIZE;
	}
	return depth;
}
```

For very large sizes, `capacity *= TREEDIRSIZE` could overflow… on a 64-bit off_t: 1024^6 blocks = 2^60 blocks = 2^72 bytes is required for depth 6. If size is capped at 2^63-1, then nblocks is at most 2^51 → depth is at most 4. capacity reaches at most 1024^5 = 2^50 < 2^63. No overflow. OK, safe.

construct_path:

```c
/**
 * Construct the path to the block file that holds a given position of
 * the export.
 *
 * @param name On input, must contain the root directory of the export
 * (i.e., the export name). On return, contains the full path of the
 * block file.
 * @param lenmax Size of the buffer that name points to
 * @param size Total size of the export
 * @param pos Position (byte offset) in the export
 * @param ppos If not NULL, on return contains the offset within the
 * block file where position pos is located
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t block;
	int depth;
	int len;
	int level;

	block = pos / TREEPAGESIZE;
	if(ppos)
		*ppos = pos % TREEPAGESIZE;
	depth = tree_depth(size);
	len = strlen(name);
	for(level = depth - 1; level >= 0; level--) {
		off_t divisor = 1;
		int i;

		for(i = 0; i < level; i++)
			divisor *= TREEDIRSIZE;
		if(len >= lenmax)
			return;
		len += snprintf(name + len, lenmax - len, "/TREE%04d", (int)((block / divisor) % TREEDIRSIZE));
	}
	if(len >= lenmax)
		return;
	snprintf(name + len, lenmax - len, "/FILE%04d", (int)(block % TREEDIRSIZE));
}
```

