/**
 * Read from a treefiles export. Reads are limited to the block file
 * containing the offset; the caller is expected to call us repeatedly
 * for data spanning multiple blocks. Block files that don't exist read
 * back as all zeroes.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error
 **/
static ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	char path[PATH_MAX];
	off_t foffset;
	ssize_t retval;
	int fd;

	if(len > TREEPAGESIZE - (a % TREEPAGESIZE))
		len = TREEPAGESIZE - (a % TREEPAGESIZE);

	strncpy(path, client->exportname, sizeof(path) - 1);
