	construct_path(path, sizeof(path), client->exportsize, a, &foffset);

	DEBUG("(READ from treefile offset %llu len %u), ", (long long unsigned int)foffset, (unsigned int)len);

	fd = open(path, O_RDONLY);
	if(fd < 0) {
		if(errno == ENOENT) {
