/**
 * Punch a hole in a treefiles export, i.e., remove the data (and the
 * block files holding it) for a given range. Whole blocks are handled
 * by removing the block file; partial blocks are handled by punching a
 * hole in the block file, if it exists.
 *
 * @param req the request for which this is being processed
 * @param client the client for which we're processing this request
 **/
static int exptrim_treefiles(struct nbd_request* req, CLIENT* client) {
	off_t a = req->from;
	size_t len = req->len;

	while(len > 0) {
		off_t foffset = a % TREEPAGESIZE;
		size_t chunk = TREEPAGESIZE - foffset;

		if(chunk > len)
