/*
 * Tree files support.
 *
 * A treefiles export stores its data in a directory (the exportname)
 * containing a tree of small block files, which is useful on
 * filesystems that do not handle large files well. Every block of
 * TREEPAGESIZE bytes of the export is stored in its own file of at
 * most TREEPAGESIZE bytes. To keep the number of entries per directory
 * limited to TREEDIRSIZE, the block files are spread over a tree of
 * subdirectories whose nesting level depends on the size of the
 * export: every directory holds at most TREEDIRSIZE block files or
 * TREEDIRSIZE subdirectories.
 */

#include "lfs.h"

#include "nbd-debug.h"
#include "treefiles.h"

#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * Work out the number of levels of subdirectories needed to hold an
 * export of the given size. A depth of 0 means all block files live
 * directly in the export's root directory.
 *
 * @param size the total size of the export, in bytes
 * @return the number of levels of subdirectories
 **/
static int tree_depth(off_t size) {
	off_t nblocks;
	off_t capacity = TREEDIRSIZE;
	int depth = 0;

	nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	while (capacity < nblocks) {
		depth++;
		capacity *= TREEDIRSIZE;
	}
	return depth;
}

void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t block;
	int depth;
	int len;
	int level;

	block = pos / TREEPAGESIZE;
	if (ppos)
		*ppos = pos % TREEPAGESIZE;
	depth = tree_depth(size);
	len = strlen(name);
	for (level = depth - 1; level >= 0; level--) {
		off_t divisor = 1;
		int i;

		for (i = 0; i < level; i++)
			divisor *= TREEDIRSIZE;
		if (len >= lenmax)
			return;
		len += snprintf(name + len, lenmax - len, "/TREE%04d",
				(int)((block / divisor) % TREEDIRSIZE));
	}
	if (len >= lenmax)
		return;
	snprintf(name + len, lenmax - len, "/FILE%04d",
		  (int)(block % TREEDIRSIZE));
}

void mkdir_path(char *path) {
	char *p;

	for (p = path + 1; *p; p++) {
		if (*p == '/') {
			*p = '\0';
			mkdir(path, 0700);
			*p = '/';
		}
	}
}

void delete_treefile(char *name, off_t size, off_t pos) {
	char path[PATH_MAX];

	strncpy(path, name, sizeof(path) - 1);
	path[sizeof(path) - 1] = '\0';
	construct_path(path, sizeof(path), size, pos, NULL);
	if (unlink(path) < 0 && errno != ENOENT) {
		DEBUG("Could not remove treefile %s: %s\n", path, strerror(errno));
	}
}

int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	int fd;

	strncpy(path, name, sizeof(path) - 1);
	path[sizeof(path) - 1] = '\0';
	construct_path(path, sizeof(path), size, pos, NULL);

	fd = open(path, mode & ~O_CREAT, 0600);
	if (fd >= 0 || errno != ENOENT || !(mode & O_CREAT))
		return fd;

	if (mutex)
		pthread_mutex_lock(mutex);
	/*
	 * Another thread may have created the file while we were
	 * waiting for the lock, so have another look before we try to
	 * create it ourselves.
	 */
	fd = open(path, mode & ~O_CREAT, 0600);
	if (fd < 0 && errno == ENOENT) {
		mkdir_path(path);
		fd = open(path, mode, 0600);
	}
	if (mutex)
		pthread_mutex_unlock(mutex);
	return fd;
}

